// Scores generated by the LLM (strength, match score, alignment score) are
// displayed across the app as percents on a 0-100 scale. When a prompt/schema
// doesn't pin that scale, models often return fractions (0-1) instead, which
// renders as nonsense like "0.95%". Normalize defensively at every boundary:
// generation, persistence, and load.
export function normalizePercent(value, fallback = null) {
  const n = typeof value === "number" ? value : parseFloat(value);
  if (!Number.isFinite(n)) return fallback;
  const scaled = n > 0 && n <= 1 ? n * 100 : n;
  return Math.min(100, Math.max(0, Math.round(scaled)));
}

// Returns a copy of a capability graph with every vector strength on 0-100.
export function normalizeCapabilityGraph(graph) {
  if (!graph || !Array.isArray(graph.core_execution_vectors)) return graph;
  return {
    ...graph,
    core_execution_vectors: graph.core_execution_vectors.map((v) => ({
      ...v,
      strength: normalizePercent(v?.strength),
    })),
  };
}
